css:
.lc { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr)); gap: 2.2rem clamp(1.5rem, 4vw, 2.75rem); margin-top: 1.8rem; }
.lc__card { border-top: 1px solid color-mix(in srgb, var(--os-color-text) 22%, transparent); padding-top: 1.2rem; }
.lc__t { margin: 0 0 .6rem; font-size: clamp(1.5rem, 1.2rem + .8vw, 1.85rem); }
.lc__p { margin: 0 0 1rem; color: var(--os-color-text-muted); }
.lc__card a { text-decoration: none; }
.lc__btn { display: inline-flex; align-items: center; min-height: 44px; padding: .45rem 1rem; border: 2px solid currentColor; border-radius: 999px; font-weight: 700; font-size: .92rem; color: var(--os-color-heading); }
.lc__btn:hover { background: color-mix(in srgb, var(--os-color-text) 8%, transparent); }
